// Bare-metal benchmark: the Triton tutorial matmul compiled by PIton,
// run on all 12 QPUs of a Pi Zero / Pi 1, checked against the ARM.
#include "rpi.h"
#include "piton_rt.h"
#include "matmul.h"          // generated by `make` (piton.tools.compile)

#ifndef MM
#define MM 256
#endif
#define BM 8
#define BN 64

static float cpu_dot(volatile float *A, volatile float *B, int i, int j, int K, int N) {
    float s = 0;
    for (int k = 0; k < K; k++)
        s += A[i * K + k] * B[k * N + j];
    return s;
}

void notmain(void) {
    const int M = MM, N = MM, K = MM_K;
    piton_init();
    printk("PIton matmul: %dx%dx%d on %d QPUs\n", M, N, K, piton_qpu_count());

    piton_buf_t a = piton_alloc(4 * M * K), b = piton_alloc(4 * K * N), c = piton_alloc(4 * M * N);
    volatile float *A = a.cpu, *B = b.cpu, *C = c.cpu;
    uint32_t s1 = 12345, s2 = 67890;
    for (int i = 0; i < M * K; i++) A[i] = piton_lcg_float(&s1);
    for (int i = 0; i < K * N; i++) B[i] = piton_lcg_float(&s2);

    matmul_args_t args = {
        .a_ptr = a.bus, .b_ptr = b.bus, .c_ptr = c.bus,
        .M = M, .N = N, .stride_am = K, .stride_bk = N, .stride_cm = N,
    };
    unsigned grid = ((M + BM - 1) / BM) * ((N + BN - 1) / BN);
    uint32_t best = ~0u;
    for (int r = 0; r < 5; r++) {
        uint32_t t = matmul_launch(&args, grid, 1, 1);
        if (t < best) best = t;
    }
    // (no integer divide on the ARM1176: use the VFP)
    float flop = 2.0f * (float)M * (float)N * (float)K;
    printk("QPU: best %d us  ->  %f GFLOPS\n", best, flop / (float)best / 1000.0f);

    // check a few entries against the ARM (QPU floats round toward zero)
    int bad = 0;
    for (int t = 0; t < 64; t++) {
        int i = (t * 37) & (M - 1), j = (t * 101) & (N - 1);   // M, N powers of two
        float ref = cpu_dot(A, B, i, j, K, N), got = C[i * N + j];
        float d = ref - got;
        if (d < 0) d = -d;
        if (d > 1e-3f * K) bad++;
    }
    uint32_t t0 = timer_get_usec();
    for (int i = 0; i < 8; i++)
        for (int j = 0; j < N; j++)
            (void)cpu_dot(A, B, i, j, K, N);
    float cpu_us = (float)(timer_get_usec() - t0) * ((float)M / 8.0f);
    printk("ARM (estimated from 8 rows): %f us -> %f GFLOPS, QPU speedup %fx\n", cpu_us,
           flop / cpu_us / 1000.0f, cpu_us / (float)best);
    printk(bad ? "CHECK FAILED (%d mismatches)\n" : "CHECK OK\n", bad);
}
